pub fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());

    for &ch in s.iter() {
        if ('A'..='Z').contains(&ch) {
            // ASCII lowercase is +32 from ASCII uppercase.
            let lower_u32 = ch as u32 + 32;
            let lower = char::from_u32(lower_u32).expect("ASCII lowercase is a valid char");
            result.push(lower);
        } else {
            result.push(ch);
        }
    }

    result
}

